exemplo.codigo:
CREATE TABLE usuarios (
  id    INTEGER PRIMARY KEY,
  nome  TEXT NOT NULL,
  email TEXT NOT NULL UNIQUE
);

CREATE TABLE pedidos (
  id         INTEGER PRIMARY KEY,
  usuario_id INTEGER NOT NULL REFERENCES usuarios(id),
  item       TEXT NOT NULL,
  valor      REAL NOT NULL
);

INSERT INTO usuarios (nome, email) VALUES
  ('Ana', 'ana@exemplo.com'),
  ('Bruno', 'bruno@exemplo.com');

INSERT INTO pedidos (usuario_id, item, valor) VALUES
  (1, 'Teclado', 199.90),
  (1, 'Mouse', 89.90),
  (2, 'Monitor', 899.00);

SELECT * FROM usuarios;
-- 1|Ana|ana@exemplo.com
-- 2|Bruno|bruno@exemplo.com

SELECT * FROM pedidos;
-- 1|1|Teclado|199.9
-- 2|1|Mouse|89.9
-- 3|2|Monitor|899.0

desafio.solucao:
PRAGMA foreign_keys = ON;

CREATE TABLE usuarios (
  id INTEGER PRIMARY KEY,
  nome TEXT NOT NULL
);

CREATE TABLE comentarios (
  id         INTEGER PRIMARY KEY,
  usuario_id INTEGER NOT NULL REFERENCES usuarios(id),
  data       TEXT NOT NULL,
  texto      TEXT NOT NULL
);

INSERT INTO usuarios (nome) VALUES ('Ana'), ('Bruno');

INSERT INTO comentarios (usuario_id, data, texto) VALUES
  (1, '2026-09-20', 'Chegou rápido.'),
  (1, '2026-09-21', 'Comprei de novo.'),
  (2, '2026-09-22', 'Veio com defeito.');

SELECT * FROM comentarios;

-- agora o usuário 99, que não existe:
-- INSERT INTO comentarios (usuario_id, data, texto)
--   VALUES (99, '2026-09-23', 'fantasma');
-- com PRAGMA foreign_keys = ON o banco recusa:
--   FOREIGN KEY constraint failed
-- sem o PRAGMA, ele aceita numa boa, e o comentário fica órfão.

exemplo.codigo:
CREATE TABLE usuarios (id INTEGER PRIMARY KEY, nome TEXT, email TEXT);
CREATE TABLE pedidos (id INTEGER PRIMARY KEY, usuario_id INTEGER, item TEXT, valor REAL);
INSERT INTO usuarios VALUES (1,'Ana','ana@exemplo.com'), (2,'Bruno','bruno@exemplo.com');
INSERT INTO pedidos VALUES (1,1,'Teclado',199.90), (2,1,'Mouse',89.90), (3,2,'Monitor',899.00);

SELECT nome, email FROM usuarios WHERE nome = 'Ana';
-- Ana|ana@exemplo.com

SELECT item, valor FROM pedidos WHERE valor > 100 ORDER BY valor DESC;
-- Monitor|899.0
-- Teclado|199.9

SELECT u.nome, p.item, p.valor
  FROM pedidos p
  JOIN usuarios u ON u.id = p.usuario_id;
-- Ana|Teclado|199.9
-- Ana|Mouse|89.9
-- Bruno|Monitor|899.0

SELECT u.nome, COUNT(*) AS quantos, SUM(p.valor) AS total
  FROM pedidos p
  JOIN usuarios u ON u.id = p.usuario_id
  GROUP BY u.nome
  ORDER BY quantos DESC;
-- Ana|2|289.8
-- Bruno|1|899.0
